function getStartWord(size){
  const lists={4:START_WORDS_4,5:START_WORDS_5,6:START_WORDS_6,7:START_WORDS_7};
  const list=lists[size]||START_WORDS_5;
  const pool=list.filter(w=>w.length===size);
  if(!pool.length) return {4:"МОВА",5:"СЛОВО",6:"РІЧКА",7:"КОЗАКИ"}[size]||"СЛОВО";
  return pool[Math.floor(Math.random()*pool.length)];
}

function isValidWord(word){
  const w = word.toUpperCase();
  return DICTIONARY.has(w) || CUSTOM_WORDS.has(w);
}